```vue src/views/WorkspaceView.vue
<script setup>
import { computed, ref, onMounted } from 'vue'
import { useRouter, useRoute } from 'vue-router'
import { $storex } from '@/store'

const router = useRouter()
const route = useRoute()

const workspaces = ref([])
const selectedWorkspace = ref(null)
const loading = ref(false)
const isDetailView = computed(() => !!route.params.workspaceId)

const workspaceId = computed(() => route.params.workspaceId)
const workspaceName = computed(() => route.params.workspaceName)

onMounted(async () => {
  await loadWorkspaces()
  if (isDetailView.value && workspaceId.value) {
    selectedWorkspace.value = workspaces.value.find(w => w.id === workspaceId.value)
  }
})

async function loadWorkspaces() {
  loading.value = true
  try {
    const project = $storex.projects.activeProject
    if (project?.$api?.workspaces) {
      const data = await project.$api.workspaces.list()
      workspaces.value = data || []
    }
  } catch (error) {
    console.error('[WorkspaceView] Failed to load workspaces:', error)
    $storex.ui.addNotification({ text: 'Failed to load workspaces', type: 'error' })
  } finally {
    loading.value = false
  }
}

function goBack() {
  if (isDetailView.value) {
    router.push({ name: 'workspaces' })
  }
}

function openWorkspace(workspace) {
  $router.$navigate.workspaces.open(workspace.id, workspace.name)
}
</script>

<template>
  <div class="flex h-full w-full bg-[#111111] text-white">
    <!-- List View or Detail View -->
    <div v-if="!isDetailView" class="w-full flex flex-col">
      <!-- Header -->
      <div class="shrink-0 flex items-center gap-3 px-4 py-3 border-b border-white/5 bg-[#111111]/80 backdrop-blur-sm">
        <h1 class="text-lg font-semibold">Workspaces</h1>
      </div>

      <!-- Loading State -->
      <div v-if="loading" class="flex-1 flex items-center justify-center">
        <div class="loading loading-spinner loading-lg text-primary"></div>
      </div>

      <!-- Workspaces List -->
      <div v-else class="flex-1 overflow-y-auto p-4">
        <div v-if="workspaces.length === 0" class="flex flex-col items-center justify-center h-full gap-3 text-white/40">
          <i class="fas fa-inbox text-4xl"></i>
          <span>No workspaces found</span>
        </div>

        <div v-else class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          <div
            v-for="workspace in workspaces"
            :key="workspace.id"
            class="p-4 rounded-lg bg-white/5 border border-white/10 hover:bg-white/10 hover:border-white/20 cursor-pointer transition-all"
            @click="openWorkspace(workspace)"
          >
            <div class="flex items-start justify-between gap-3">
              <div class="flex-1 min-w-0">
                <h3 class="font-medium text-white truncate">{{ workspace.name }}</h3>
                <p v-if="workspace.description" class="text-xs text-white/50 truncate mt-1">
                  {{ workspace.description }}
                </p>
              </div>
              <div class="text-white/30">
                <i class="fas fa-chevron-right"></i>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- Detail View -->
    <div v-else class="w-full flex flex-col">
      <!-- Header with back button -->
      <div class="shrink-0 flex items-center gap-3 px-4 py-3 border-b border-white/5 bg-[#111111]/80 backdrop-blur-sm">
        <button
          class="p-1.5 text-white/40 hover:text-white transition-colors"
          @click="goBack"
        >
          <i class="fas fa-arrow-left text-sm"></i>
        </button>
        <div class="flex-1 min-w-0">
          <h2 class="text-sm font-medium text-white/80 truncate">{{ workspaceName }}</h2>
        </div>
      </div>

      <!-- Workspace Content -->
      <div class="flex-1 overflow-y-auto p-4">
        <div class="max-w-4xl mx-auto">
          <!-- Placeholder for workspace content -->
          <div class="flex flex-col items-center justify-center gap-4 py-12 text-white/40">
            <i class="fas fa-briefcase text-6xl"></i>
            <h3 class="text-lg font-medium">{{ workspaceName }}</h3>
            <p class="text-sm">Workspace content coming soon</p>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<style scoped>
/* Add scoped styles if needed */
</style>
