          this.loadProfilesForChat()
          this.$nextTick(() => this.scrollToBottom())
        }
        this.showMobileChats = false
        this.selectedWorkspaceApp = null
      } catch (err) {
        console.error('[QuickChat] openChat error', err)
      } finally {
        this.isChatLoading = false
      }
    },

