## Implementation

```js src/router/navigate.js
export default function Navigate({ $router, $storex }) {

  let historyRegistered = false

  const $navigation = {
    // ════════════════════════════════════════════════════════════════
    // STATE GETTERS - Read current route state
    // ════════════════════════════════════════════════════════════════

    getCurrentRoute() {
      return $router.currentRoute.value
    },

    getChatId() {
      return $router.currentRoute.value.params.chatId || null
    },

    getChatName() {
      return $router.currentRoute.value.params.chatName || null
    },

    getWorkspaceId() {
      return $router.currentRoute.value.params.workspaceId || null
    },

    getWorkspaceName() {
      return $router.currentRoute.value.params.workspaceName || null
    },

    // ════════════════════════════════════════════════════════════════
    // ROUTE STATE FLAGS - Identify current view
    // ════════════════════════════════════════════════════════════════

    get isDesktopMode() {
      return $router.currentRoute.value.name === 'codx-junior-split'
    },

    get isMobileMode() {
      return $router.currentRoute.value.name === 'mobile'
    },

    get isChatView() {
      const name = $router.currentRoute.value.name
      return name === 'chat' || name === 'chat-workspace'
    },

    get isWorkspaceView() {
      const name = $router.currentRoute.value.name
      return name === 'workspace' || name === 'workspaces'
    },

    get isKanbanView() {
      return $router.currentRoute.value.name === 'kanban'
    },

    get isMessengerView() {
      return $router.currentRoute.value.name === 'messenger'
    },

    get isHomeView() {
      return $router.currentRoute.value.name === 'home'
    },

    get hasChatContext() {
      return this.getChatId() !== null
    },

    get hasWorkspaceContext() {
      return this.getWorkspaceId() !== null
    },

    // ════════════════════════════════════════════════════════════════
    // INITIALIZATION
    // ════════════════════════════════════════════════════════════════

    init() {
      // Initialize history state on first load
      if (window.history.length === 1) {
        window.history.replaceState(null, '', '/')
        window.history.pushState(null, '', window.location.href)
      }
    },

    async onRouteChanged({ from, to }) {
      // ── OAuth callback ────────────────────────────────────────────
      if (to.path.startsWith('/auth')) {
        const { code, state } = to.query
        const provider = to.path.split('/').reverse()[0]

        if (!provider || !code) {
          $storex.session.onError('Missing OAuth provider or code')
          return '/'
        }

        try {
          await $storex.users.oauthLogin({ provider, code, state })
          return '/'
        } catch (error) {
          $storex.session.onError('Failed to complete OAuth login')
          return '/'
        }
      }

      // ── Standalone routes with name (opt-out of mobile/desktop redirect) ─
      if (!!to.name) {
        return true
      }

      // ── Mobile redirect ──────────────────────────────────────────
      if ($storex.ui.isMobile && to.name !== 'mobile') {
        return { name: 'mobile', replace: true }
      }

      // ── Desktop: redirect /mobile → home ─────────────────────────
      if (!$storex.ui.isMobile && to.name === 'mobile') {
        return { name: 'home', replace: true }
      }

      return true
    },

    // ════════════════════════════════════════════════════════════════
    // CHAT NAVIGATION
    // ════════════════════════════════════════════════════════════════

    navigateToChat(chat) {
      if (!chat?.id) {
        console.warn('[Navigation] navigateToChat: invalid chat', chat)
        return
      }

      const chatName = chat.name || `chat-${chat.id}`
      const isDesktopMode = this.isDesktopMode

      if (isDesktopMode) {
        // Desktop mode: show as app panel
        $storex.ui.showApp({
          tabId: chat.id,
          name: chatName,
          component: 'chat',
          params: {
            chat: {
              id: chat.id,
              name: chatName,
              owner_project_id: chat.owner_project_id || $storex.projects.activeProject?.project_id
            }
          }
        })
      } else {
        // Router mode: push to chat route
        $router.push({
          name: 'chat',
          params: {
            chatId: chat.id,
            chatName: chatName
          }
        })
      }
    },

    // ════════════════════════════════════════════════════════════════
    // WORKSPACE NAVIGATION
    // ════════════════════════════════════════════════════════════════

    navigateToWorkspace(workspace) {
      if (!workspace?.id) {
        console.warn('[Navigation] navigateToWorkspace: invalid workspace', workspace)
        return
      }

      const workspaceName = workspace.name || `workspace-${workspace.id}`
      const isDesktopMode = this.isDesktopMode

      if (isDesktopMode) {
        // Desktop mode: show as app panel
        $storex.ui.showApp({
          tabId: `workspace-${workspace.id}`,
          name: workspaceName,
          component: 'workspace',
          params: {
            workspace: {
              id: workspace.id,
              name: workspaceName
            }
          }
        })
      } else {
        // Router mode: navigate to workspace route
        $router.push({
          name: 'workspace',
          params: {
            workspaceId: workspace.id,
            workspaceName: workspaceName
          }
        })
      }
    },

    navigateToWorkspaces() {
      const isDesktopMode = this.isDesktopMode

      if (isDesktopMode) {
        // Desktop mode: show as app panel
        $storex.ui.showApp({
          tabId: 'workspaces-list',
          name: 'Workspaces',
          component: 'workspaces',
          params: {}
        })
      } else {
        // Router mode: navigate to workspaces list
        $router.push({ name: 'workspaces' })
      }
    },

    // ════════════════════════════════════════════════════════════════
    // CHAT + WORKSPACE COMBINED NAVIGATION
    // ════════════════════════════════════════════════════════════════

    addWorkspaceToChat(chat, workspace) {
      if (!chat?.id || !workspace?.id) {
        console.warn('[Navigation] addWorkspaceToChat: invalid chat or workspace', { chat, workspace })
        return
      }

      const chatName = chat.name || `chat-${chat.id}`
      const workspaceName = workspace.name || `workspace-${workspace.id}`
      const isDesktopMode = this.isDesktopMode

      if (isDesktopMode) {
        // Desktop mode: show chat with workspace context in params
        $storex.ui.showApp({
          tabId: chat.id,
          name: chatName,
          component: 'chat',
          params: {
            chat: {
              id: chat.id,
              name: chatName,
              owner_project_id: chat.owner_project_id || $storex.projects.activeProject?.project_id
            },
            workspace: {
              id: workspace.id,
              name: workspaceName
            }
          }
        })
      } else {
        // Router mode: push to chat-workspace route
        $router.push({
          name: 'chat-workspace',
          params: {
            chatId: chat.id,
            chatName: chatName,
            workspaceId: workspace.id,
            workspaceName: workspaceName
          }
        })
      }
    },

    // ════════════════════════════════════════════════════════════════
    // PRIMARY APP NAVIGATION
    // ════════════════════════════════════════════════════════════════

    navigateToDesktop() {
      $router.push({ name: 'codx-junior-split' })
    },

    navigateToHome() {
      $router.push({ name: 'home' })
    },

    navigateToMessenger() {
      const isDesktopMode = this.isDesktopMode

      if (isDesktopMode) {
        $storex.ui.showApp({
          tabId: 'messenger',
          name: 'Messenger',
          component: 'messenger',
          params: {}
        })
      } else {
        $router.push({ name: 'messenger' })
      }
    },

    navigateToKanban() {
      const isDesktopMode = this.isDesktopMode

      if (isDesktopMode) {
        $storex.ui.showTab('tasks')
      } else {
        $router.push({ name: 'kanban' })
      }
    },

    navigateToMobile() {
      $router.push({ name: 'mobile' })
    },

    // ════════════════════════════════════════════════════════════════
    // ADDITIONAL APP NAVIGATION (From sidebar)
    // ════════════════════════════════════════════════════════════════

    navigateToNewChat() {
      $router.push({ name: 'home' })
    },

    navigateToTaskManager() {
      this.navigateToKanban()
    },

    navigateToFileExplorer() {
      const isDesktopMode = this.isDesktopMode
      if (isDesktopMode) {
        $storex.ui.showTab('files')
      } else {
        $router.push({ path: '/files' })
      }
    },

    navigateToWiki() {
      const isDesktopMode = this.isDesktopMode
      if (isDesktopMode) {
        $storex.ui.showTab('wiki')
      } else {
        $router.push({ path: '/wiki' })
      }
    },

    navigateToTeam() {
      const isDesktopMode = this.isDesktopMode
      if (isDesktopMode) {
        $storex.ui.showApp({
          tabId: 'team',
          name: 'Team',
          component: 'team',
          params: {}
        })
      } else {
        $router.push({ path: '/team' })
      }
    },

    navigateToViews() {
      const isDesktopMode = this.isDesktopMode
      if (isDesktopMode) {
        $storex.ui.showApp({
          tabId: 'views',
          name: 'Views',
          component: 'views',
          params: {}
        })
      } else {
        $router.push({ path: '/views' })
      }
    },

    navigateToProfiles() {
      const isDesktopMode = this.isDesktopMode
      if (isDesktopMode) {
        $storex.ui.showApp({
          tabId: 'profiles',
          name: 'Profiles',
          component: 'profiles',
          params: {}
        })
      } else {
        $router.push({ path: '/profiles' })
      }
    },

    navigateToKnowledge() {
      const isDesktopMode = this.isDesktopMode
      if (isDesktopMode) {
        $storex.ui.showApp({
          tabId: 'knowledge',
          name: 'Knowledge',
          component: 'knowledge',
          params: {}
        })
      } else {
        $router.push({ path: '/knowledge' })
      }
    },

    navigateToAnalytics() {
      const isDesktopMode = this.isDesktopMode
      if (isDesktopMode) {
        $storex.ui.showApp({
          tabId: 'analytics',
          name: 'Analytics',
          component: 'analytics',
          params: {}
        })
      } else {
        $router.push({ path: '/analytics' })
      }
    }
  }

  return $navigation
}
