<script>
export default {
  components: {
    NavItem,
    RecentsSection,
    UserInfo
  },
  props: {
    userName: { type: String, default: 'User' },
    userSubtitle: { type: String, default: 'Pro' },
    isMobile: { type: Boolean, default: false },
    isMobileExpanded: { type: Boolean, default: false }
  },
  emits: ['settings', 'close'],
  data() {
    return {
      isCollapsed: false,
      userCollapsed: false,
      moreExpanded: false,
      primaryNavExpanded: true,
      workspacesExpanded: true,
      recentsExpanded: true,
      resizeObserver: null,
      recentChats: [],
      isLoadingChats: false,
      currentPage: 1,
      initialPageSize: 20,
      subsequentPageSize: 10,
      hasMoreChats: true,
      activeChattId: null,
      isInitialLoad: true,
      dailyLimitStatus: 'normal',
      selectedWorkspaceApp: null
    }
  },
  computed: {
    workspaceApps() {
      return this.$projects.projectApps || []
    },
    currentUser() {
      return this.$storex?.users?.user || this.$user
    },
    hasWorkspaceApps() {
      return this.workspaceApps && this.workspaceApps.length > 0
    },
    isProjectAdmin() {
      return this.$users?.isProjectAdmin || false
    }
  },
  mounted() {
    if (!this.isMobile) {
      this.$nextTick(() => this.setupResizeObserver())
    }
    this.loadRecentChats()
    this.loadWorkspaceApps()
  },
  beforeUnmount() {
    this.resizeObserver?.disconnect()
  },
  methods: {
    setupResizeObserver() {
      const el = this.$refs.sidebarEl
      if (!el) return
      const parent = el.parentElement
      if (!parent) return
      this.resizeObserver = new ResizeObserver(([entry]) => {
        const width = entry.contentRect.width
        if (!this.userCollapsed) {
          this.isCollapsed = width < 600
        }
      })
      this.resizeObserver.observe(parent)
    },
    toggleCollapse() {
      this.userCollapsed = !this.userCollapsed
      this.isCollapsed = this.userCollapsed
    },
    handleClose() {
      this.$emit('close')
    },
    handleMoreClick() {
      if (this.isCollapsed && !this.isMobileExpanded) {
        this.toggleCollapse()
