<script>
export default {
  components: {
    NavItem,
    RecentsSection,
    UserInfo
  },
  props: {
    userName: { type: String, default: 'User' },
    userSubtitle: { type: String, default: 'Pro' },
    isMobile: { type: Boolean, default: false },
    isMobileExpanded: { type: Boolean, default: false }
  },
  emits: ['settings', 'close'],
  data() {
    return {
      isCollapsed: false,
      userCollapsed: false,
      moreExpanded: false,
      primaryNavExpanded: true,
      workspacesExpanded: true,
      recentsExpanded: true,
      resizeObserver: null,
      recentChats: [],
      isLoadingChats: false,
      currentPage: 1,
      initialPageSize: 20,
      subsequentPageSize: 10,
      hasMoreChats: true,
      activeChattId: null,
      isInitialLoad: true,
      dailyLimitStatus: 'normal',
      selectedWorkspaceApp: null
    }
  },
  computed: {
    workspaceApps() {
      return this.$projects.projectApps || []
    },
    currentUser() {
      return this.$storex?.users?.user || this.$user
    },
    hasWorkspaceApps() {
      return this.workspaceApps && this.workspaceApps.length > 0
    },
    isProjectAdmin() {
      return this.$users?.isProjectAdmin || false
    }
  },
  mounted() {
    if (!this.isMobile) {
      this.$nextTick(() => this.setupResizeObserver())
    }
    this.loadRecentChats()
    this.loadWorkspaceApps()
  },
  beforeUnmount() {
    this.resizeObserver?.disconnect()
  },
  methods: {
    setupResizeObserver() {
      const el = this.$refs.sidebarEl
      if (!el) return
      const parent = el.parentElement
      if (!parent) return
      this.resizeObserver = new ResizeObserver(([entry]) => {
        const width = entry.contentRect.width
        if (!this.userCollapsed) {
          this.isCollapsed = width < 600
        }
      })
      this.resizeObserver.observe(parent)
    },
    toggleCollapse() {
      this.userCollapsed = !this.userCollapsed
      this.isCollapsed = this.userCollapsed
    },
    handleClose() {
      this.$emit('close')
    },
    handleMoreClick() {
      if (this.isCollapsed && !this.isMobileExpanded) {
        this.toggleCollapse()
      } else {
        this.toggleMore()
      }
    },
    toggleMore() {
      this.moreExpanded = !this.moreExpanded
    },
    handleNavigateToNewChat() {
      this.$storex.$router.$navigation.apps.openHome()
      if (this.isMobileExpanded) {
        this.handleClose()
      }
    },
    handleNavigateToKanban() {
      this.$storex.$router.$navigation.apps.openKanban()
      if (this.isMobileExpanded) {
        this.handleClose()
      }
    },
    handleNavigateToDesktop() {
      this.$storex.$router.$navigation.apps.openDesktop()
      if (this.isMobileExpanded) {
        this.handleClose()
      }
    },
    handleNavigateToMessenger() {
      this.$storex.$router.$navigation.apps.openMessenger()
      if (this.isMobileExpanded) {
        this.handleClose()
      }
    },
    handleNavigateToFileExplorer() {
      this.$storex.$router.$navigation.apps.openFileExplorer()
      if (this.isMobileExpanded) {
        this.handleClose()
      }
    },
    handleNavigateToWiki() {
      this.$storex.$router.$navigation.apps.openWiki()
      if (this.isMobileExpanded) {
        this.handleClose()
      }
    },
    handleNavigateToHome() {
      this.$storex.$router.$navigation.apps.openHome()
      if (this.isMobileExpanded) {
        this.handleClose()
      }
    },
    handleShowNewProject() {
      this.$ui.showNewProject(true)
      if (this.isMobileExpanded) {
        this.handleClose()
      }
    },
    handleNavigateToTeam() {
      this.$storex.$router.$navigation.apps.openTeam()
      if (this.isMobileExpanded) {
        this.handleClose()
      }
    },
    handleNavigateToViews() {
      this.$storex.$router.$navigation.apps.openViews()
      if (this.isMobileExpanded) {
        this.handleClose()
      }
    },
    handleNavigateToProfiles() {
      this.$storex.$router.$navigation.apps.openProfiles()
      if (this.isMobileExpanded) {
        this.handleClose()
      }
    },
    handleNavigateToKnowledge() {
      this.$storex.$router.$navigation.apps.openKnowledge()
      if (this.isMobileExpanded) {
        this.handleClose()
      }
    },
    handleNavigateToAnalytics() {
      this.$storex.$router.$navigation.apps.openAnalytics()
      if (this.isMobileExpanded) {
        this.handleClose()
      }
    },
    handleLogout() {
      this.$users.logout()
    },
    async loadRecentChats(append = false) {
      try {
        this.isLoadingChats = true
        const currentUserId = this.currentUser?.id
        const pageSize = this.isInitialLoad ? this.initialPageSize : this.subsequentPageSize

        const response = await this.$project.$api.chats.getRecentChats({
          filters: { user_id: currentUserId },
          page: this.currentPage,
          pageSize: pageSize
        })

        if (response.error) {
          console.error('Error loading recent chats:', response.error)
          this.isLoadingChats = false
          return
        }

        if (append) {
          this.recentChats.push(...response.chats)
        } else {
          this.recentChats = response.chats
        }

        this.hasMoreChats = response.has_next
        this.activeChattId = this.$storex?.chats?.activeChat?.id || null
        this.isLoadingChats = false
        this.isInitialLoad = false
      } catch (error) {
        console.error('Error loading recent chats:', error)
        this.isLoadingChats = false
      }
    },
    loadMoreChats() {
      if (this.hasMoreChats && !this.isLoadingChats) {
        this.currentPage += 1
        this.loadRecentChats(true)
      }
    },
    handleSelectChat(chat) {
      this.$chats.setActiveChat(chat)
      if (this.isMobileExpanded) {
        this.handleClose()
      }
    },
    loadWorkspaceApps() {
      this.workspaceApps = this.$projects.projectApps || []
      this.selectedWorkspaceApp = this.workspaceApps[0] || null
    },
    handleSelectWorkspaceApp(app) {
      this.selectedWorkspaceApp = app
      this.$storex.$router.$navigation.workspaces.open(app.id, app.name)
      if (this.isMobileExpanded) {
        this.handleClose()
      }
    },
    isWorkspaceSelected(workspaceId) {
      return this.$storex.$router.$navigation.getWorkspaceId() === workspaceId
    }
  }
}
</script>

