      },

      openWiki() {
        if ($navigation.isDesktopMode) {
          $storex.ui.showTab('wiki')
        } else {
          $router.push({ path: '/wiki' })
        }
      },

      openTeam() {
        if ($navigation.isDesktopMode) {
          $storex.ui.showApp({
            tabId: 'team',
            name: 'Team',
            component: 'team',
            params: {}
          })
        } else {
          $router.push({ path: '/team' })
        }
      },

      openViews() {
        if ($navigation.isDesktopMode) {
          $storex.ui.showApp({
            tabId: 'views',
            name: 'Views',
            component: 'views',
            params: {}
          })
        } else {
          $router.push({ path: '/views' })
        }
      },

      openProfiles() {
        if ($navigation.isDesktopMode) {
          $storex.ui.showApp({
            tabId: 'profiles',
            name: 'Profiles',
            component: 'profiles',
            params: {}
          })
        } else {
          $router.push({ path: '/profiles' })
