const router = createRouter({
  history: createWebHistory(import.meta.env.BASE_URL),
  routes: [
    {
      // Teams-like launcher home page
      path: '/',
      name: 'home',
      component: QuickChatView
    },
    {
      // Chat routes: router mode
      path: '/chats',
